#!/usr/bin/env python3
"""
natal_aspect.py — composer for natal-chart aspects (aspects between your OWN birth planets).

A character reading, not a dated event (transit) or a relationship (composite/synastry).
Structure: lived experience (two concrete ways the dynamic shows up), then guidance, then the
technical aspect as a footer. Marie's plain full-form voice; planet-accurate; no em dashes.

Astronomical reality is respected: Mercury and Venus never stray far from the Sun, so certain
aspects between them cannot occur natally and are never emitted (CONSTRAINTS below).
"""
DISP = {"sun":"your Sun","moon":"your Moon","mercury":"your Mercury","venus":"your Venus",
        "mars":"your Mars","jupiter":"your Jupiter","saturn":"your Saturn","uranus":"your Uranus",
        "neptune":"your Neptune","pluto":"your Pluto"}
BARE = {k: v.replace("your ", "") for k, v in DISP.items()}
ASPECT_WORD = {"conjunction":"conjunct","square":"square","opposition":"opposite",
               "trine":"trine","sextile":"sextile"}
ASPECT_VERB = {"conjunction":"conjuncts","square":"squares","opposition":"opposes",
               "trine":"trines","sextile":"sextiles"}
VALENCE = {"conjunction":"fused","trine":"flowing","sextile":"flowing","square":"friction","opposition":"friction"}
ALL5 = {"conjunction","square","opposition","trine","sextile"}

# astronomically possible natal aspects for the tight inner pairs (else all 5)
CONSTRAINTS = {
 "mercury-sun": {"conjunction"},               # Mercury never > ~28 deg from the Sun
 "sun-venus":   {"conjunction"},               # Venus never > ~47 deg from the Sun
 "mercury-venus": {"conjunction", "sextile"},  # max separation ~76 deg
}
OUTER_SLOW = {"uranus", "neptune", "pluto"}

