def _key(a, b): return "-".join(sorted([a, b]))
def is_allowed(a, b, aspect): return aspect in CONSTRAINTS.get(_key(a, b), ALL5)
def is_authored(a, b): return _key(a, b) in PAIRS

def compose_natal_aspect(a, b, aspect):
    key = _key(a, b)
    if key not in PAIRS or aspect not in CONSTRAINTS.get(key, ALL5):
        return None
    p = PAIRS[key]; A, B = key.split("-")
    val = VALENCE[aspect]
    astro = f"{DISP[A]} {ASPECT_VERB[aspect]} {DISP[B]}"
    generational = A in OUTER_SLOW and B in OUTER_SLOW
    # named fields so the app maps to body/sections deterministically (not by paragraph position,
    # which varies when the generational note is present)
    experience = p[val]
    guidance = p["navigation"]
    note = ("This one is shared by everyone born around your time, so hold it as generational "
            "background rather than something that singles you out.") if generational else None
    paras = [experience]
    if note:
        paras.append(note)
    paras.append(guidance)
    paras.append(f"The astro: {astro}.")
    return {"title": f"{BARE[A]} {ASPECT_WORD[aspect]} {BARE[B]}",
            "eyebrow": {"label": "Natal aspect", "pair": key, "aspect": aspect, "valence": val,
                        "theme": p["theme"], "generational": generational},
            "generational": generational,
            "astro": astro,
            "experience": experience, "guidance": guidance, "note": note,
            "paragraphs": paras,
            "trace": {"pair": key, "aspect": aspect,
                      "sourceKeys": [f"cc/planet/{A}", f"cc/planet/{B}"],
                      "readerAuthority": "composed-reviewed"}}
